    %#0规定为左结合的。#1 应解释为 #2%(
        Syntax.apply-UTLC,
        Syntax.apply-UTLC(x, y, z, w),
        Syntax.apply-UTLC(
            parentheses(
                Syntax.apply-UTLC(
                    parentheses(Syntax.apply-UTLC(x, y)),
