        )
    ),
    %运算优先级上 #0较 #1结合更加紧密。#2 应解释为 #3%(Syntax.apply-UTLC, Syntax.Expr-UTLC.lambda, Syntax.Expr-UTLC.lambda(list-partial[none](@x, @y), Syntax.apply-UTLC(x, y)),Syntax.Expr-UTLC.lambda(list-partial[none](@x, @y), parentheses(Syntax.apply-UTLC(x, y))))
)

list-partial[enumerate](
    %通常将 #0表达式根据 #1记作形如 #2 的表达式。%(Syntax.Expr-UTLC.lambda, deBruijnIndex ,Syntax.Expr-UTLC.lambda(@x, P(x)),),
    %将形如 #0 的多元函数记作 #1%(
        Syntax.Expr-UTLC.lambda(
            @x,
            Syntax.Expr-UTLC.lambda(@y, Type.apply(P(x), y))
        ),
        Syntax.Expr-UTLC.lambda(list-partial[none](@x, @y), Type.apply(P(x), y))
    )
)
